fn clone_vec(b: &Vec<f64>) -> Vec<f64> {
    b.clone() // Cloning the vector
}

fn solve(a: Vec<Vec<f64>>, b: Vec<f64>) -> Vec<f64> {
    let n = a.len();
    let mut augmented_matrix = a.clone();

    // Create the augmented matrix [A | b]
    for i in 0..n {
        augmented_matrix[i].push(b[i]);
    }

    // Perform Gaussian elimination
    for i in 0..n {
        // Make the diagonal contain all 1s
        let diag = augmented_matrix[i][i];
        for j in 0..(n + 1) {
            augmented_matrix[i][j] /= diag;
        }

        // Eliminate the current column in the rows below
        for k in (i + 1)..n {
            let factor = augmented_matrix[k][i];
            for j in 0..(n + 1) {
                augmented_matrix[k][j] -= factor * augmented_matrix[i][j];
            }
        }
    }

    // Back substitution to find the solution
    let mut result = vec![0.0; n];
    for i in (0..n).rev() {
        result[i] = augmented_matrix[i][n]; // The last column contains the solution
        for j in (i + 1)..n {
            result[i] -= augmented_matrix[i][j] * result[j];
        }
    }

    result
}